def parse_csv_line(line: str, delimiter: str = ",") -> list[str]:
    if not isinstance(delimiter, str) or len(delimiter) != 1 or delimiter == '"':
        raise ValueError("delimiter must be a single character other than '\"'")

    fields: list[str] = []
    i = 0
    n = len(line)

    while True:
        if i == n:
            fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            j = i + 1
            buf: list[str] = []
            closed = False

            while j < n:
                c = line[j]
                if c == '"':
                    if j + 1 < n and line[j + 1] == '"':
                        buf.append('"')
                        j += 2
                    else:
                        closed = True
                        j += 1
                        break
                else:
                    buf.append(c)
                    j += 1

            if not closed:
                raise ValueError("unterminated quoted field")

            if j < n:
                if line[j] != delimiter:
                    raise ValueError("unexpected character after closing quote")
                fields.append(''.join(buf))
                i = j + 1
                continue
            else:
                fields.append(''.join(buf))
                break
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != delimiter:
                if line[i] == '"':
                    raise ValueError("quote in unquoted field")
                i += 1

            fields.append(line[start:i])

            if i < n and line[i] == delimiter:
                i += 1
                continue
            else:
                break

    return fields
