def _decode_token(token: str) -> str:
    if '~' not in token:
        return token

    out = []
    i = 0
    n = len(token)

    while i < n:
        ch = token[i]
        if ch == '~':
            if i + 1 >= n:
                raise ValueError("invalid JSON Pointer escape: '~' at end of token")
            nxt = token[i + 1]
            if nxt == '1':
                out.append('/')
            elif nxt == '0':
                out.append('~')
            else:
                raise ValueError(f"invalid JSON Pointer escape: '~{nxt}'")
            i += 2
        else:
            out.append(ch)
            i += 1

    return ''.join(out)


def _list_index(token: str) -> int:
    if token == "-":
        raise KeyError("list index '-' refers to nonexistent element")

    if not token or not all('0' <= c <= '9' for c in token):
        raise ValueError(f"invalid list index token: {token!r}")

    if len(token) > 1 and token[0] == '0':
        raise ValueError(f"invalid list index token: {token!r}")

    return int(token)


def resolve_pointer(doc, pointer: str):
    if pointer == "":
        return doc

    if not pointer.startswith("/"):
        raise ValueError("JSON Pointer must be empty or start with '/'")

    tokens = pointer[1:].split('/')
    decoded_tokens = [_decode_token(token) for token in tokens]

    current = doc

    for token in decoded_tokens:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            idx = _list_index(token)
            if idx >= len(current):
                raise KeyError(f"list index {idx} out of range")
            current = current[idx]
        else:
            raise KeyError(f"cannot apply token {token!r} to {type(current).__name__}")

    return current
