import re

_DATE_RE = re.compile(
    r'(?:([0-9]+(?:[.,][0-9]+)?)Y)?'
    r'(?:([0-9]+(?:[.,][0-9]+)?)M)?'
    r'(?:([0-9]+(?:[.,][0-9]+)?)W)?'
    r'(?:([0-9]+(?:[.,][0-9]+)?)D)?'
)
_TIME_RE = re.compile(
    r'(?:([0-9]+(?:[.,][0-9]+)?)H)?'
    r'(?:([0-9]+(?:[.,][0-9]+)?)M)?'
    r'(?:([0-9]+(?:[.,][0-9]+)?)S)?'
)

def parse_duration(s: str) -> float:
    if not isinstance(s, str):
        raise ValueError("input must be a string")
    if not s.startswith('P'):
        raise ValueError("missing leading P")
    rest = s[1:]
    if rest == "":
        raise ValueError("no components")

    if 'T' in rest:
        if rest.count('T') != 1:
            raise ValueError("multiple T separators")
        date_str, time_str = rest.split('T')
        if time_str == "":
            raise ValueError("T with no time components")
    else:
        date_str, time_str = rest, None

    date_match = _DATE_RE.fullmatch(date_str)
    if date_match is None:
        raise ValueError("invalid date part")

    components = []
    date_factors = {'Y': 365 * 86400, 'M': 30 * 86400, 'W': 7 * 86400, 'D': 86400}
    for i, designator in enumerate(('Y', 'M', 'W', 'D')):
        num = date_match.group(i + 1)
        if num is not None:
            components.append((num, date_factors[designator]))

    if time_str is not None:
        time_match = _TIME_RE.fullmatch(time_str)
        if time_match is None:
            raise ValueError("invalid time part")
        time_factors = {'H': 3600, 'M': 60, 'S': 1}
        for i, designator in enumerate(('H', 'M', 'S')):
            num = time_match.group(i + 1)
            if num is not None:
                components.append((num, time_factors[designator]))

    if not components:
        raise ValueError("no components")

    for i, (num, _) in enumerate(components):
        if i < len(components) - 1 and ('.' in num or ',' in num):
            raise ValueError("fractional part only allowed on last component")

    total = 0.0
    for num, factor in components:
        total += float(num.replace(',', '.')) * factor
    return total
